const FEEDING_TYPES = new Set(['FORMULA','MIXED','SOLID'])

function validateFeedingPlan(input) {
  const ageFromMonths=integer(input.ageFromMonths,'起始月龄（月）',0,240),ageFromDays=integer(input.ageFromDays,'起始月龄（天）',0,30),ageToMonths=integer(input.ageToMonths,'结束月龄（月）',0,240),ageToDays=integer(input.ageToDays,'结束月龄（天）',0,30),temperatureMin=integer(input.temperatureMin,'最低水温',0,100),temperatureMax=integer(input.temperatureMax,'最高水温',temperatureMin,100)
  ensure(ageToMonths * 31 + ageToDays >= ageFromMonths * 31 + ageFromDays,'VALIDATION_ERROR','结束年龄不能小于起始年龄')
  const feedingType=input.feedingType || 'FORMULA'
  ensure(FEEDING_TYPES.has(feedingType),'VALIDATION_ERROR','食物方案类型无效')
  return {name:text(input.name,'方案名称',80),species:text(input.species,'适用品种',60),stage:text(input.stage,'生长阶段',40),ageFromMonths,ageFromDays,ageToMonths,ageToDays,formulaName:text(input.formulaName,'奶粉名称',100,false),waterMl:integer(input.waterMl,'水量',0,1000),powderScoops:text(input.powderScoops,'奶粉勺数',40,false),temperatureMin,temperatureMax,feedingsPerDay:integer(input.feedingsPerDay,'每日次数',0,24),amountMl:text(input.amountMl,'单次参考量',60,false),feedingMethod:text(input.feedingMethod,'喂养方式',40,false),temperatureCheck:text(input.temperatureCheck,'水温判断',500,false),preparationNotes:text(input.preparationNotes,'冲泡说明',1000,false),feedingNotes:text(input.feedingNotes,'喂养注意事项',1500,false),fullnessNotes:text(input.fullnessNotes,'喂饱判断',1000,false),warningNotes:text(input.warningNotes,'异常提醒',1000,false),feedingType,seedFoodName:text(input.seedFoodName,'谷子或固体食物',100,false),seedFoodAmount:text(input.seedFoodAmount,'谷子或固体食物用量',100,false),seedFoodNotes:text(input.seedFoodNotes,'谷子或固体食物说明',1000,false)}
}

function feedingPlanView(row) { return {id:row.id,name:row.name,species:row.species,stage:row.stage,ageFromMonths:Number(row.age_from_months),ageFromDays:Number(row.age_from_days || 0),ageToMonths:Number(row.age_to_months),ageToDays:Number(row.age_to_days || 0),isEnabled:Boolean(row.is_enabled),formulaName:row.formula_name,waterMl:Number(row.water_ml),powderScoops:row.powder_scoops,temperatureMin:Number(row.temperature_min),temperatureMax:Number(row.temperature_max),feedingsPerDay:Number(row.feedings_per_day),amountMl:row.amount_ml,feedingMethod:row.feeding_method,temperatureCheck:row.temperature_check,preparationNotes:row.preparation_notes,feedingNotes:row.feeding_notes,fullnessNotes:row.fullness_notes,warningNotes:row.warning_notes,feedingType:row.feeding_type || 'FORMULA',seedFoodName:row.seed_food_name || '',seedFoodAmount:row.seed_food_amount || '',seedFoodNotes:row.seed_food_notes || '',revision:Number(row.revision),updatedAt:row.updated_at} }

function validateSupply(input) {
  const category = input.category
  ensure(category === 'SUPPLY' || category === 'MEDICINE', 'VALIDATION_ERROR', '耗材分类无效')
  const purchaseDate = dateOnly(input.purchaseDate, '购买时间')
  const today = new Date(Date.now() + 28800000).toISOString().slice(0, 10)
  ensure(purchaseDate <= today, 'VALIDATION_ERROR', '购买时间不能晚于今天')
  return { category, name: text(input.name, '名称', 100), amountCents: integer(input.amountCents, '金额', 1, 99999999900), weight: text(input.weight, '重量', 60, false), purchaseDate, notes: text(input.notes, '备注', 1000, false) }
}

function supplyView(row) { return { id: row.id, category: row.category, name: row.name, amountCents: Number(row.amount_cents), weight: row.weight || '', purchaseDate: row.purchase_date, notes: row.notes || '', createdAt: row.created_at } }

function validateParrot(input, partial = false) {
  const result = {}; const has = key => Object.prototype.hasOwnProperty.call(input || {}, key)
  if (!partial || has('breed')) result.breed = text(input.breed,'品种',60)
  if (!partial || has('species')) result.species = text(input.species,'名称',60)
  if (!partial || has('ringNumber')) { result.ringNumber=text(input.ringNumber,'脚环',40,false); result.ringNumberNormalized=normalizeRing(result.ringNumber); if(result.ringNumber)ensure(result.ringNumberNormalized,'VALIDATION_ERROR','脚环无效') }
  if (!partial || has('gender')) { ensure(GENDERS.has(input.gender),'VALIDATION_ERROR','性别无效'); result.gender=input.gender }
  if (!partial || has('birthDate')) { result.birthDate=dateOnly(input.birthDate,'出生日期'); const sh=new Date(Date.now()+28800000); const today=`${sh.getUTCFullYear()}-${String(sh.getUTCMonth()+1).padStart(2,'0')}-${String(sh.getUTCDate()).padStart(2,'0')}`; ensure(result.birthDate<=today,'VALIDATION_ERROR','出生日期不能晚于今天') }
  if (!partial || has('priceCents')) result.priceCents=integer(input.priceCents,'价格',0,99999999900)
  if (!partial || has('publicIntro')) result.publicIntro=text(input.publicIntro,'公开介绍',1000,false)
  if (!partial || has('privateNotes')) result.privateNotes=text(input.privateNotes,'内部备注',3000,false)
  if (!partial || has('media')) { ensure(Array.isArray(input.media)&&input.media.length<=20,'VALIDATION_ERROR','媒体数量无效'); result.media=input.media.map(item=>({assetId:text(item.assetId,'媒体标识',80),type:item.type})) }
  return result
}

function validatePurchaseDate(input) {
  const purchaseDate = dateOnly(input.purchaseDate, '购买日期')
  const sh = new Date(Date.now() + 28800000)
  const today = `${sh.getUTCFullYear()}-${String(sh.getUTCMonth() + 1).padStart(2, '0')}-${String(sh.getUTCDate()).padStart(2, '0')}`
  ensure(purchaseDate <= today, 'VALIDATION_ERROR', '购买日期不能晚于今天')
  return purchaseDate
}

function validateParent(input, label, partial = false) {
  if (input == null || input === '') return partial ? undefined : null
  ensure(input && typeof input === 'object', 'VALIDATION_ERROR', `${label}信息无效`)
  const source = input.source
  ensure(source === 'LIBRARY' || source === 'MANUAL', 'VALIDATION_ERROR', `${label}来源无效`)
  if (source === 'LIBRARY') return { source, id: text(input.id, `${label}档案`, 80) }
  return { source, species: text(input.species, `${label}品种`, 60), ringNumber: text(input.ringNumber, `${label}脚环`, 40, false) }
}

async function isDescendant(env, owner, candidateId, birdId) {
  const pending = [candidateId], seen = new Set()
  while (pending.length) {
    const current = pending.pop()
    if (!current || seen.has(current)) continue
    if (current === birdId) return true
    seen.add(current)
    ensure(seen.size <= 32, 'VALIDATION_ERROR', '血统关系层级异常')
    const row = await first(env, 'SELECT father_id,mother_id FROM parrots WHERE id=? AND owner_open_id=?', current, owner)
    if (row) pending.push(row.father_id, row.mother_id)
  }
  return false
}

async function resolveParent(env, owner, input, expectedGender, label, birdId) {
  if (!input) return null
  if (input.source === 'MANUAL') return { source: 'MANUAL', id: null, species: input.species, ringNumber: input.ringNumber || '' }
  ensure(input.id !== birdId, 'VALIDATION_ERROR', `${label}不能选择本鸟`)
  const parent = await owned(env, 'parrots', input.id, owner)
  ensure(parent.gender === expectedGender, 'VALIDATION_ERROR', `${label}必须选择${expectedGender === 'MALE' ? '公鸟' : '母鸟'}`)
  ensure(!(await isDescendant(env, owner, parent.id, birdId)), 'VALIDATION_ERROR', '不能形成循环血统')
  return { source: 'LIBRARY', id: parent.id, species: parent.species, ringNumber: parent.ring_number }
}

function validateOffspringGroups(input, hatched) {
  if (input == null) return undefined
  ensure(Array.isArray(input) && input.length <= 20, 'VALIDATION_ERROR', '出窝品种明细无效')
  const names = new Set(); const groups = input.map(item => {
    const species = text(item && item.species, '出窝品种', 60)
    ensure(!names.has(species), 'VALIDATION_ERROR', '同一品种只能填写一次'); names.add(species)
    return { species, count: integer(item && item.count, '出窝数量', 1, 100) }
  })
  ensure(groups.reduce((sum, item) => sum + item.count, 0) <= hatched, 'VALIDATION_ERROR', '品种数量不能超过出壳数量')
  return groups
}

function validateClutchChicks(input, expectedCount) {
  ensure(Array.isArray(input) && input.length === expectedCount, 'VALIDATION_ERROR', `请完整录入本窝${expectedCount}只幼鸟`)
  const rings = new Set()
  return input.map((item, index) => {
    const breed = text(item && item.breed, `第${index + 1}只幼鸟品种`, 60)
    const species = text(item && item.species, `第${index + 1}只幼鸟名称`, 60)
    const ringNumber = text(item && item.ringNumber, `第${index + 1}只幼鸟脚环`, 40, false)
    const normalized = normalizeRing(ringNumber)
    ensure(!normalized || !rings.has(normalized), 'VALIDATION_ERROR', '同一窝幼鸟的脚环不能重复')
    if (normalized) rings.add(normalized)
    ensure(GENDERS.has(item && item.gender), 'VALIDATION_ERROR', `第${index + 1}只幼鸟性别无效`)
    return { breed, species, ringNumber, ringNumberNormalized: normalized, gender: item.gender, priceCents: integer(item && item.priceCents, `第${index + 1}只幼鸟估值`, 0, 99999999900), privateNotes: text(item && item.privateNotes, `第${index + 1}只幼鸟备注`, 3000, false) }
  })
}

async function validateMedia(env, owner, items) {
  const output=[]; const seen=new Set()
  for(const item of items||[]){ ensure(['image','video'].includes(item.type),'VALIDATION_ERROR','媒体类型无效'); ensure(!seen.has(item.assetId),'VALIDATION_ERROR','媒体不能重复'); seen.add(item.assetId); const asset=await first(env,'SELECT * FROM media_assets WHERE id=? AND owner_open_id=? AND status=? AND deleted_at IS NULL',item.assetId,owner,'COMMITTED'); ensure(asset&&asset.type===item.type,'VALIDATION_ERROR','媒体尚未完成上传'); output.push({assetId:asset.id,type:asset.type,key:asset.object_key}) }
  return output
}

async function receipt(env, owner, requestId) { return first(env,'SELECT * FROM command_receipts WHERE receipt_id=?',await sha256(`${owner}:${requestId}`)) }
function receiptResult(row) { return parseJson(row.result_json,{}) }

async function saveBatch(env, owner, action, requestId, statements, result) {
  const receiptId=await sha256(`${owner}:${requestId}`)
  statements.push(statement(env,'INSERT INTO command_receipts (receipt_id,owner_open_id,request_id,action,result_json,created_at) VALUES (?,?,?,?,?,?)',receiptId,owner,requestId,action,json(action==='shares.create'?{parrotId:result.parrotId,expiresAt:result.expiresAt}:result),nowIso()))
  try { await env.DB.batch(statements) } catch(error) { const message=String(error&&error.message||''); if(['parrots.create','parrots.update'].includes(action)&&/unique|parrots_owner_ring/i.test(message)) throw new ApiError('DUPLICATE_RING','脚环已存在',409); throw error }
  return result
}

export async function executeCommand(env, owner, action, input, requestId, actorOpenId = null) {
  ensure(WRITE_ACTIONS.has(action),'NOT_FOUND','接口不存在',404); text(requestId,'requestId',100)
  const existing=await receipt(env,owner,requestId)
  if(existing){ ensure(existing.action===action,'CONFLICT','请求号已用于其他操作',409); const stored=receiptResult(existing); if(action==='shares.create') return {...stored,token:await deriveShareToken(owner,requestId,env.SHARE_TOKEN_SECRET)}; return stored }
  const result=await commandHandlers[action](env,owner,input||{},requestId,actorOpenId)
  const data=await saveBatch(env,owner,action,requestId,result.statements,result.data)
  await purgeReleasedMedia(env,owner,result.releasedAssetIds)
  return data
}

const RECYCLE_WINDOW_MS = 15 * 86400000

async function parrotPurgeStatements(env, owner, bird, requestId) {
  const sales=await all(env,'SELECT media_json FROM sales_records WHERE owner_open_id=? AND parrot_id=?',owner,bird.id)
  const releasedAssetIds=[...mediaIds(rowMedia(bird)),...sales.flatMap(row=>mediaIds(rowMedia(row)))]
  return { releasedAssetIds, statements:[statement(env,'DELETE FROM sale_copy_documents WHERE owner_open_id=? AND parrot_id=?',owner,bird.id),statement(env,'DELETE FROM share_tokens WHERE owner_open_id=? AND parrot_id=?',owner,bird.id),statement(env,'DELETE FROM hatching_records WHERE owner_open_id=? AND (male_id=? OR female_id=?)',owner,bird.id,bird.id),statement(env,'DELETE FROM breeding_pairs WHERE owner_open_id=? AND (male_id=? OR female_id=?)',owner,bird.id,bird.id),statement(env,'DELETE FROM sales_records WHERE owner_open_id=? AND parrot_id=?',owner,bird.id),statement(env,'DELETE FROM parrots WHERE id=? AND owner_open_id=?',bird.id,owner),auditStatement(env,owner,'parrots.purge','parrot',bird.id,requestId,bird,{purged:true,deletedAt:bird.deleted_at})] }
}

export async function purgeExpiredParrots(env) {
  const cutoff=new Date(Date.now()-RECYCLE_WINDOW_MS).toISOString()
  const rows=await all(env,'SELECT * FROM parrots WHERE deleted_at IS NOT NULL AND deleted_at<=? ORDER BY deleted_at ASC LIMIT 100',cutoff)
  for(const bird of rows){
    const purge=await parrotPurgeStatements(env,bird.owner_open_id,bird,`scheduled-purge:${bird.id}:${bird.deleted_at}`)
    await env.DB.batch(purge.statements)
    await purgeReleasedMedia(env,bird.owner_open_id,purge.releasedAssetIds)
  }
  return rows.length
}

function mediaIds(items){ return [...new Set((items||[]).map(item=>item&&item.assetId).filter(Boolean))] }
function removedMediaIds(before,after){ const next=new Set(mediaIds(after)); return mediaIds(before).filter(assetId=>!next.has(assetId)) }
async function purgeReleasedMedia(env,owner,assetIds=[]){
  for(const assetId of new Set(assetIds)){
    const asset=await first(env,'SELECT * FROM media_assets WHERE id=? AND owner_open_id=?',assetId,owner)
    if(!asset)continue
    const referenced=await first(env,"SELECT 1 AS found FROM parrots,json_each(parrots.media_json) WHERE parrots.owner_open_id=? AND json_extract(json_each.value,'$.assetId')=? UNION ALL SELECT 1 AS found FROM sales_records,json_each(sales_records.media_json) WHERE sales_records.owner_open_id=? AND json_extract(json_each.value,'$.assetId')=? LIMIT 1",owner,assetId,owner,assetId)
    if(referenced)continue
    try{
      if(asset.status==='PENDING'&&asset.upload_id)await cosAbortMultipartUpload(env,asset.object_key,asset.upload_id)
      else await cosDeleteObject(env,asset.object_key)
      await env.DB.prepare('DELETE FROM media_assets WHERE id=? AND owner_open_id=?').bind(assetId,owner).run()
    }catch(error){ console.error('[media purge]',assetId,error) }
  }
}

async function simpleStatus(env,owner,input,requestId,from,to,action){ const bird=await owned(env,'parrots',text(input.id,'id',80),owner); revisionCheck(bird,input.revision); ensure(bird.status===from,'INVALID_STATE','当前状态不允许执行该操作'); const now=nowIso(),next={...bird,status:to,revision:bird.revision+1,updated_at:now}; return {data:{id:bird.id,revision:next.revision},statements:[statement(env,'UPDATE parrots SET status=?,revision=?,updated_at=? WHERE id=?',to,next.revision,now,bird.id),auditStatement(env,owner,action,'parrot',bird.id,requestId,bird,next)]} }

async function closePair(env,owner,pair,reason,requestId,now){ const male=await owned(env,'parrots',pair.male_id,owner),female=await owned(env,'parrots',pair.female_id,owner); if(reason==='HATCHING_CANCELLED'||reason==='HATCHING_COMPLETED')return [statement(env,'UPDATE breeding_pairs SET status=?,revision=revision+1,updated_at=? WHERE id=?','ACTIVE',now,pair.id),statement(env,'UPDATE parrots SET status=?,active_pair_id=?,revision=revision+1,updated_at=? WHERE id IN (?,?)',STATUS.PAIRED,pair.id,now,male.id,female.id),auditStatement(env,owner,'hatching.resumePair','breedingPair',pair.id,requestId,pair,{status:'ACTIVE',hatching:reason})]; return [statement(env,'UPDATE breeding_pairs SET status=?,ended_at=?,end_reason=?,revision=revision+1,updated_at=? WHERE id=?','CLOSED',now,reason,now,pair.id),statement(env,'UPDATE parrots SET status=?,active_pair_id=NULL,paired_at=NULL,revision=revision+1,updated_at=? WHERE id IN (?,?)',STATUS.BREEDER,now,male.id,female.id),auditStatement(env,owner,`breeding.${reason.toLowerCase()}`,'breedingPair',pair.id,requestId,pair,{status:'CLOSED',endReason:reason})] }

async function createParrot(env, owner, input, requestId, source) {
  const value = validateParrot(input), media = await validateMedia(env, owner, value.media), now = nowIso(), birdId = id()
  const father = await resolveParent(env, owner, validateParent(input.father, '父鸟'), 'MALE', '父鸟', birdId), mother = await resolveParent(env, owner, validateParent(input.mother, '母鸟'), 'FEMALE', '母鸟', birdId)
  ensure(!(father && mother && father.source === 'LIBRARY' && mother.source === 'LIBRARY' && father.id === mother.id), 'VALIDATION_ERROR', '父鸟和母鸟不能为同一只鸟')
  const purchaseDate = source === 'INTRODUCTION' ? validatePurchaseDate(input) : null
  const data = { id: birdId, owner_open_id: owner, breed: value.breed, species: value.species, ring_number: value.ringNumber, ring_number_normalized: value.ringNumberNormalized, gender: value.gender, status: STATUS.FOR_SALE, birth_date: value.birthDate, price_cents: value.priceCents, public_intro: value.publicIntro, private_notes: value.privateNotes, media_json: json(media), father_id: father && father.id, mother_id: mother && mother.id, father_snapshot_json: json(father), mother_snapshot_json: json(mother), active_pair_id: null, paired_at: null, revision: 1, created_at: now, updated_at: now, deleted_at: null, deleted_by: null, record_source: source, purchase_date: purchaseDate, introduction_stage: source === 'INTRODUCTION' ? 'GROWING' : null }
  return { data: { id: birdId, revision: 1 }, statements: [statement(env, 'INSERT INTO parrots (id,owner_open_id,breed,species,ring_number,ring_number_normalized,gender,status,birth_date,price_cents,public_intro,private_notes,media_json,father_id,mother_id,father_snapshot_json,mother_snapshot_json,active_pair_id,paired_at,revision,created_at,updated_at,deleted_at,deleted_by,record_source,purchase_date,introduction_stage) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)', ...Object.values(data)), auditStatement(env, owner, source === 'INTRODUCTION' ? 'introductions.create' : 'parrots.create', 'parrot', birdId, requestId, null, data)] }
}

