async function createFromClutch(env,owner,input,requestId){
  const record=await owned(env,'hatching_records',text(input.hatchingRecordId,'孵化记录',80),owner)
  revisionCheck(record,input.revision)
  ensure(record.status==='COMPLETED'&&record.hatched>0,'INVALID_STATE','请在孵化完成且有幼鸟出壳后再录入')
  const existing=await first(env,'SELECT id FROM parrots WHERE owner_open_id=? AND birth_hatching_record_id=? AND deleted_at IS NULL LIMIT 1',owner,record.id)
  ensure(!existing,'INVALID_STATE','本窝幼鸟已录入，不能重复创建')
  const chicks=validateClutchChicks(input.chicks,record.hatched),father=await owned(env,'parrots',record.male_id,owner),mother=await owned(env,'parrots',record.female_id,owner)
  const fatherSnapshot={source:'LIBRARY',id:father.id,species:father.species,ringNumber:father.ring_number},motherSnapshot={source:'LIBRARY',id:mother.id,species:mother.species,ringNumber:mother.ring_number}
  const birthDate=dateOnly(String(record.completed_at||record.updated_at||record.start_date).slice(0,10),'出生日期'),now=nowIso(),statements=[],created=[]
  for(const chick of chicks){
    const data={id:id(),owner_open_id:owner,breed:chick.breed,species:chick.species,ring_number:chick.ringNumber,ring_number_normalized:chick.ringNumberNormalized,gender:chick.gender,status:STATUS.FOR_SALE,birth_date:birthDate,price_cents:chick.priceCents,public_intro:'',private_notes:chick.privateNotes,media_json:'[]',father_id:father.id,mother_id:mother.id,father_snapshot_json:json(fatherSnapshot),mother_snapshot_json:json(motherSnapshot),birth_hatching_record_id:record.id,active_pair_id:null,paired_at:null,revision:1,created_at:now,updated_at:now,deleted_at:null,deleted_by:null}
    statements.push(statement(env,'INSERT INTO parrots (id,owner_open_id,breed,species,ring_number,ring_number_normalized,gender,status,birth_date,price_cents,public_intro,private_notes,media_json,father_id,mother_id,father_snapshot_json,mother_snapshot_json,birth_hatching_record_id,active_pair_id,paired_at,revision,created_at,updated_at,deleted_at,deleted_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',...Object.values(data)),auditStatement(env,owner,'parrots.createFromClutch','parrot',data.id,requestId,null,data))
    created.push(data.id)
  }
  return {data:{ids:created,birthDate},statements}
}

async function createHatching(env,owner,input,requestId){ const male=await owned(env,'parrots',text(input.maleId,'maleId',80),owner),female=await owned(env,'parrots',text(input.femaleId,'femaleId',80),owner); revisionCheck(male,input.maleRevision); revisionCheck(female,input.femaleRevision); ensure(male.gender==='MALE'&&female.gender==='FEMALE','INVALID_STATE','孵化父母必须为公鸟和母鸟'); const breeders=male.status===STATUS.BREEDER&&female.status===STATUS.BREEDER,paired=male.status===STATUS.PAIRED&&female.status===STATUS.PAIRED&&male.active_pair_id&&male.active_pair_id===female.active_pair_id; ensure(breeders||paired,'INVALID_STATE','父母鸟状态不允许启动孵化'); const duplicate=await first(env,'SELECT id FROM hatching_records WHERE owner_open_id=? AND male_id=? AND female_id=? AND status=? AND deleted_at IS NULL',owner,male.id,female.id,'INCUBATING'); ensure(!duplicate,'INVALID_STATE','该组合已有进行中的孵化任务'); const now=nowIso(),statements=[]; let pairId,pairRevision=1,pairedAt=now;if(paired){ const pair=await owned(env,'breeding_pairs',male.active_pair_id,owner); ensure(pair.status==='ACTIVE','INVALID_STATE','配对状态异常'); if(input.pairRevision!=null)revisionCheck(pair,input.pairRevision); pairId=pair.id;pairRevision=pair.revision+1;pairedAt=pair.paired_at;statements.push(statement(env,'UPDATE breeding_pairs SET status=?,revision=?,updated_at=? WHERE id=?','INCUBATING',pairRevision,now,pairId)) }else{ pairId=id();statements.push(statement(env,'INSERT INTO breeding_pairs (id,owner_open_id,male_id,female_id,status,paired_at,ended_at,end_reason,revision,created_at,updated_at,deleted_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,?)',pairId,owner,male.id,female.id,'INCUBATING',now,null,null,1,now,now,null)) } const recordId=id(),eggs=integer(input.eggs,'蛋数量',1,100),species=text(input.species,'品种',60),startDate=dateOnly(input.startDate,'开始日期'),record={id:recordId,owner_open_id:owner,pair_id:pairId,male_id:male.id,female_id:female.id,male_ring_number:male.ring_number,female_ring_number:female.ring_number,species,start_date:startDate,eggs,hatched:0,offspring_json:'[]',status:'INCUBATING',completed_at:null,revision:1,created_at:now,updated_at:now,deleted_at:null,deleted_by:null};statements.push(statement(env,'INSERT INTO hatching_records (id,owner_open_id,pair_id,male_id,female_id,male_ring_number,female_ring_number,species,start_date,eggs,hatched,offspring_json,status,completed_at,revision,created_at,updated_at,deleted_at,deleted_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',...Object.values(record)));statements.push(statement(env,'UPDATE parrots SET status=?,active_pair_id=?,paired_at=?,revision=revision+1,updated_at=? WHERE id IN (?,?)',STATUS.INCUBATING,pairId,pairedAt,now,male.id,female.id));statements.push(auditStatement(env,owner,'hatching.create','hatchingRecord',recordId,requestId,null,record));return {data:{id:recordId,revision:1},statements} }

async function finishHatching(env,owner,input,requestId,deleting){ const record=await owned(env,'hatching_records',text(input.id,'id',80),owner); revisionCheck(record,input.revision); const now=nowIso(),statements=[]; if(record.status==='INCUBATING'){ const pair=await owned(env,'breeding_pairs',record.pair_id,owner); ensure(pair.status==='INCUBATING','INVALID_STATE','配对状态异常'); statements.push(...await closePair(env,owner,pair,deleting?'HATCHING_CANCELLED':'HATCHING_COMPLETED',requestId,now)) }else if(!deleting)throw new ApiError('INVALID_STATE','孵化任务已经完成'); if(deleting){ const chicks=await first(env,'SELECT id FROM parrots WHERE owner_open_id=? AND birth_hatching_record_id=? AND deleted_at IS NULL LIMIT 1',owner,record.id); ensure(!chicks,'INVALID_STATE','本窝已有幼鸟档案，不能移除孵化记录'); statements.push(statement(env,'DELETE FROM hatching_records WHERE id=? AND owner_open_id=?',record.id,owner),auditStatement(env,owner,'hatching.delete','hatchingRecord',record.id,requestId,record,{deleted:true})); return {data:{id:record.id,deleted:true},statements} } const next={...record,status:'COMPLETED',completed_at:now,revision:record.revision+1,updated_at:now};statements.push(statement(env,'UPDATE hatching_records SET status=?,completed_at=?,revision=?,updated_at=? WHERE id=?','COMPLETED',now,next.revision,now,record.id));statements.push(auditStatement(env,owner,'hatching.complete','hatchingRecord',record.id,requestId,record,next));return {data:{id:record.id,revision:next.revision},statements} }

export async function executeRead(env,owner,action,input,baseUrl,sessionToken){
  if(action==='sync.snapshot'){ const [parrots,pairs,hatching,sales,dashboardData]=await Promise.all([executeRead(env,owner,'parrots.list',{},baseUrl,sessionToken),executeRead(env,owner,'breeding.listActive',{},baseUrl,sessionToken),executeRead(env,owner,'hatching.list',{},baseUrl,sessionToken),executeRead(env,owner,'sales.list',{},baseUrl,sessionToken),executeRead(env,owner,'dashboard.get',{},baseUrl,sessionToken)]); return {parrots,pairs,hatching,sales,dashboard:dashboardData} }
  if(action==='parrots.list'){ const rows=await all(env,'SELECT * FROM parrots WHERE owner_open_id=? AND deleted_at IS NULL ORDER BY created_at DESC',owner); return {items:await Promise.all(rows.map(row=>serializeParrot(env,row,env.MEDIA_SIGNING_SECRET,baseUrl,sessionToken))),nextCursor:null} }
  if(action==='parrots.recycleBin'){ const cutoff=new Date(Date.now()-RECYCLE_WINDOW_MS).toISOString(),rows=await all(env,'SELECT * FROM parrots WHERE owner_open_id=? AND deleted_at IS NOT NULL AND deleted_at>? ORDER BY deleted_at DESC',owner,cutoff); const items=await Promise.all(rows.map(async row=>({...(await serializeParrot(env,row,env.MEDIA_SIGNING_SECRET,baseUrl,sessionToken)),deletedAt:row.deleted_at,purgeAt:new Date(new Date(row.deleted_at).getTime()+RECYCLE_WINDOW_MS).toISOString()}))); return {items,nextCursor:null} }
  if(action==='parrots.get'){ return serializeParrot(env,await owned(env,'parrots',text(input.id,'id',80),owner),env.MEDIA_SIGNING_SECRET,baseUrl,sessionToken) }
  if(action==='feedingPlans.list'){ const rows=await all(env,'SELECT * FROM feeding_plans WHERE owner_open_id=? AND deleted_at IS NULL ORDER BY species,age_from_months,name',owner); return rows.map(feedingPlanView) }
  if(action==='supplies.list'){ const rows=await all(env,'SELECT * FROM supply_records WHERE owner_open_id=? ORDER BY purchase_date DESC,created_at DESC',owner); return rows.map(supplyView) }
  if(action==='breeding.listActive'){ const pairs=await all(env,"SELECT * FROM breeding_pairs WHERE owner_open_id=? AND deleted_at IS NULL AND status IN ('ACTIVE','INCUBATING') ORDER BY paired_at DESC",owner),result=[]; for(const pair of pairs){ const male=await owned(env,'parrots',pair.male_id,owner),female=await owned(env,'parrots',pair.female_id,owner); result.push({id:pair.id,maleId:pair.male_id,femaleId:pair.female_id,status:pair.status,pairedAt:pair.paired_at,revision:pair.revision,createdAt:pair.created_at,updatedAt:pair.updated_at,male:await serializeParrot(env,male,env.MEDIA_SIGNING_SECRET,baseUrl,sessionToken),female:await serializeParrot(env,female,env.MEDIA_SIGNING_SECRET,baseUrl,sessionToken)}) } return result }
  if(action==='hatching.list'){ const rows=await all(env,'SELECT h.*,p.paired_at AS pairing_date,male.species AS male_species,female.species AS female_species,(SELECT COUNT(*) FROM parrots chick WHERE chick.owner_open_id=h.owner_open_id AND chick.birth_hatching_record_id=h.id AND chick.deleted_at IS NULL) AS offspring_registered FROM hatching_records h LEFT JOIN breeding_pairs p ON p.id=h.pair_id AND p.owner_open_id=h.owner_open_id LEFT JOIN parrots male ON male.id=h.male_id AND male.owner_open_id=h.owner_open_id LEFT JOIN parrots female ON female.id=h.female_id AND female.owner_open_id=h.owner_open_id WHERE h.owner_open_id=? AND h.deleted_at IS NULL ORDER BY h.start_date DESC,h.created_at DESC',owner),items=await Promise.all(rows.map(async row=>{const offspring=await all(env,'SELECT id,ring_number FROM parrots WHERE owner_open_id=? AND birth_hatching_record_id=? AND deleted_at IS NULL ORDER BY created_at,id',owner,row.id);return{id:row.id,pairId:row.pair_id,maleId:row.male_id,femaleId:row.female_id,maleSnapshot:{species:row.male_species||row.species,ringNumber:row.male_ring_number},femaleSnapshot:{species:row.female_species||row.species,ringNumber:row.female_ring_number},pairingDate:row.pairing_date||'',species:row.species,startDate:row.start_date,eggs:row.eggs,hatched:row.hatched,offspringGroups:parseJson(row.offspring_json,[]),offspring:offspring.map(chick=>({id:chick.id,ringNumber:chick.ring_number||''})),status:row.status,revision:row.revision,completedAt:row.completed_at||'',offspringRegistered:Number(row.offspring_registered||0),createdAt:row.created_at,updatedAt:row.updated_at}})); return {items,nextCursor:null} }
  if(action==='sales.list'){ const rows=await all(env,'SELECT * FROM sales_records WHERE owner_open_id=? AND deleted_at IS NULL ORDER BY sale_date DESC,created_at DESC',owner),items=[]; for(const row of rows){items.push({id:row.id,parrotId:row.parrot_id,parrotSnapshot:{breed:row.breed||'',species:row.species,ringNumber:row.ring_number,gender:row.gender,birthDate:row.birth_date,media:await mediaItems(env,parseJson(row.media_json,[]),env.MEDIA_SIGNING_SECRET,baseUrl,sessionToken)},buyer:row.buyer,buyerContact:row.buyer_contact,saleDate:row.sale_date,priceCents:row.price_cents,status:row.status,returnReason:row.return_reason,followUpStatus:row.follow_up_status,revision:row.revision,createdAt:row.created_at})} return {items,nextCursor:null} }
  if(action==='shares.list')return (await all(env,'SELECT token_hash AS id,parrot_id AS parrotId,expires_at AS expiresAt,revoked_at AS revokedAt,created_at AS createdAt FROM share_tokens WHERE owner_open_id=? AND deleted_at IS NULL ORDER BY created_at DESC',owner))
  if(action==='ai.saleCopy.generate')return generateSaleCopy(env,owner,input||{})
  if(action==='dashboard.get')return dashboard(env,owner)
  throw new ApiError('NOT_FOUND','接口不存在',404)
}

async function dashboard(env,owner){ const parrots=await all(env,'SELECT status,species,record_source,introduction_stage FROM parrots WHERE owner_open_id=? AND deleted_at IS NULL',owner),sales=await all(env,'SELECT status,price_cents,sale_date FROM sales_records WHERE owner_open_id=? AND deleted_at IS NULL',owner),stats={total:parrots.length,forSale:0,sold:0,returned:0,breeder:0,paired:0,incubating:0,revenueCents:0,salesTotal:sales.length,returnRate:0};const keys={FOR_SALE:'forSale',SOLD:'sold',RETURNED:'returned',BREEDER:'breeder',PAIRED:'paired',INCUBATING:'incubating'};parrots.forEach(item=>{if(item.status==='FOR_SALE'&&item.record_source==='INTRODUCTION'&&item.introduction_stage!=='FOR_SALE')return;if(keys[item.status])stats[keys[item.status]]++});const valid=sales.filter(item=>item.status==='COMPLETED');stats.revenueCents=valid.reduce((sum,item)=>sum+item.price_cents,0);stats.returnRate=sales.length?Math.round(sales.filter(item=>item.status==='RETURNED').length/sales.length*100):0;const mix={};parrots.forEach(item=>mix[item.species]=(mix[item.species]||0)+1);const species=Object.entries(mix).map(([name,count])=>({name,count,percent:parrots.length?Math.round(count/parrots.length*100):0})).sort((a,b)=>b.count-a.count).slice(0,5);const now=new Date(),trend=[];for(let offset=5;offset>=0;offset--){const date=new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()-offset,1)),month=`${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}`,monthSales=valid.filter(item=>item.sale_date.startsWith(month));trend.push({month,revenueCents:monthSales.reduce((sum,item)=>sum+item.price_cents,0),volume:monthSales.length})}return {stats,species,trend} }
